create extension if not exists pgcrypto;
create type public.app_role as enum ('TEACHER','STUDENT');
create type public.publish_status as enum ('DRAFT','PUBLISHED');
create type public.assessment_state as enum ('IN_PROGRESS','SUBMITTED','GRADED');
create type public.recommendation_state as enum ('ACTIVE','ACCEPTED','DISMISSED');

create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text not null,full_name text not null default '',role public.app_role not null default 'STUDENT',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index profiles_email_lower_uq on public.profiles(lower(email));
create table public.classes(id uuid primary key default gen_random_uuid(),name text not null check(length(trim(name)) between 1 and 100),grade smallint check(grade between 1 and 12),school_year text,owner_teacher_id uuid not null references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table public.class_members(class_id uuid not null references public.classes(id) on delete cascade,student_id uuid not null references public.profiles(id) on delete cascade,joined_at timestamptz not null default now(),primary key(class_id,student_id));
create index class_members_student_idx on public.class_members(student_id);
create table public.class_invites(id uuid primary key default gen_random_uuid(),class_id uuid not null references public.classes(id) on delete cascade,code text not null unique,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),expires_at timestamptz,revoked_at timestamptz);
create table public.courses(id uuid primary key default gen_random_uuid(),class_id uuid not null references public.classes(id) on delete cascade,title text not null,description text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table public.course_topics(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses(id) on delete cascade,title text not null,description text not null default '',display_order integer not null default 0,status public.publish_status not null default 'DRAFT',created_at timestamptz not null default now(),deleted_at timestamptz,unique(id,course_id));
create table public.lessons(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses(id) on delete cascade,topic_id uuid not null,title text not null,description text not null default '',status public.publish_status not null default 'DRAFT',display_order integer not null default 0,created_at timestamptz not null default now(),deleted_at timestamptz,unique(id,course_id),foreign key(topic_id,course_id) references public.course_topics(id,course_id));
create table public.learning_objectives(id uuid primary key default gen_random_uuid(),lesson_id uuid not null references public.lessons(id) on delete cascade,code text not null,description text not null,unique(lesson_id,code));
create table public.resources(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses(id) on delete cascade,lesson_id uuid references public.lessons(id) on delete set null,file_name text not null,storage_path text not null unique,file_size_bytes bigint not null check(file_size_bytes between 1 and 52428800),mime_type text not null,uploaded_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),deleted_at timestamptz);
create table public.assignments(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses(id) on delete cascade,topic_id uuid,lesson_id uuid,title text not null,description text not null default '',due_at timestamptz not null,allow_late boolean not null default false,late_close_at timestamptz,max_score numeric(7,2) not null check(max_score>0),max_attempts integer not null default 1 check(max_attempts>=1),status public.publish_status not null default 'DRAFT',created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),deleted_at timestamptz,check(num_nonnulls(topic_id,lesson_id)<=1),check((not allow_late and late_close_at is null) or (allow_late and late_close_at>due_at)),foreign key(topic_id,course_id) references public.course_topics(id,course_id),foreign key(lesson_id,course_id) references public.lessons(id,course_id));
create table public.assignment_submissions(id uuid primary key default gen_random_uuid(),assignment_id uuid not null references public.assignments(id),student_id uuid not null references public.profiles(id),text_content text,storage_path text,status text not null check(status in ('SUBMITTED','LATE')),score numeric(7,2),feedback text,graded_by uuid references public.profiles(id),graded_at timestamptz,is_edited boolean not null default false,submitted_at timestamptz not null default now(),unique(assignment_id,student_id),check(score is null or score>=0),check(text_content is not null or storage_path is not null));
create table public.questions(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses(id) on delete cascade,content text not null,kind text not null check(kind in ('SINGLE_CHOICE','MULTIPLE_CHOICE','TRUE_FALSE','SHORT_ANSWER','ESSAY')),options jsonb not null default '[]'::jsonb,correct_answer jsonb,difficulty text not null default 'MEDIUM',created_by uuid not null references public.profiles(id),deleted_at timestamptz);
create table public.assessments(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses(id) on delete cascade,topic_id uuid,lesson_id uuid,title text not null,duration_minutes integer not null check(duration_minutes>0),max_attempts integer not null check(max_attempts>=1),open_at timestamptz not null,close_at timestamptz not null,status public.publish_status not null default 'DRAFT',created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),deleted_at timestamptz,check(close_at>open_at),check(num_nonnulls(topic_id,lesson_id)<=1),foreign key(topic_id,course_id) references public.course_topics(id,course_id),foreign key(lesson_id,course_id) references public.lessons(id,course_id));
create table public.assessment_questions(assessment_id uuid not null references public.assessments(id) on delete cascade,question_id uuid not null references public.questions(id),weight numeric(7,2) not null check(weight>0),display_order integer not null default 0,primary key(assessment_id,question_id));
create table public.assessment_attempts(id uuid primary key default gen_random_uuid(),assessment_id uuid not null references public.assessments(id),student_id uuid not null references public.profiles(id),attempt_number integer not null check(attempt_number>=1),status public.assessment_state not null default 'IN_PROGRESS',started_at timestamptz not null default now(),submitted_at timestamptz,graded_at timestamptz,total_score numeric(7,2),unique(assessment_id,student_id,attempt_number));
create unique index one_live_attempt on public.assessment_attempts(assessment_id,student_id) where status='IN_PROGRESS';
create table public.submission_answers(id uuid primary key default gen_random_uuid(),attempt_id uuid not null references public.assessment_attempts(id) on delete cascade,question_id uuid not null references public.questions(id),answer_content jsonb,score numeric(7,2),feedback text not null default '',graded_by uuid references public.profiles(id),graded_at timestamptz,unique(attempt_id,question_id));
create table public.mastery(student_id uuid not null references public.profiles(id),objective_id uuid not null references public.learning_objectives(id),mastery_score numeric(5,4) not null check(mastery_score between 0 and 1),evidence_count integer not null default 0,updated_at timestamptz not null default now(),primary key(student_id,objective_id));
create table public.knowledge_gaps(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id),objective_id uuid not null references public.learning_objectives(id),status text not null default 'OPEN' check(status in ('OPEN','RESOLVED','DISMISSED')),reason text,dismissed_by uuid references public.profiles(id),dismiss_reason text,opened_at timestamptz not null default now());
create table public.recommendations(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id),objective_id uuid references public.learning_objectives(id),kind text not null,reason text not null default '',status public.recommendation_state not null default 'ACTIVE',created_at timestamptz not null default now(),responded_at timestamptz);
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,type text not null,title text not null,content text not null default '',is_read boolean not null default false,created_at timestamptz not null default now(),read_at timestamptz);

create function public.current_app_role() returns public.app_role language sql stable security definer set search_path=public,pg_temp as $$ select role from public.profiles where id=auth.uid() $$;
create function public.can_manage_class(x uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select exists(select 1 from public.classes c where c.id=x and c.owner_teacher_id=auth.uid() and c.deleted_at is null) $$;
create function public.can_access_class(x uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select public.can_manage_class(x) or exists(select 1 from public.class_members m join public.classes c on c.id=m.class_id where m.class_id=x and m.student_id=auth.uid() and c.deleted_at is null) $$;
create function public.can_manage_course(x uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select exists(select 1 from public.courses c where c.id=x and public.can_manage_class(c.class_id) and c.deleted_at is null) $$;
create function public.can_access_course(x uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select exists(select 1 from public.courses c where c.id=x and public.can_access_class(c.class_id) and c.deleted_at is null) $$;
create function public.can_manage_assignment(x uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select exists(select 1 from public.assignments a where a.id=x and public.can_manage_course(a.course_id)) $$;
create function public.can_manage_assessment(x uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select exists(select 1 from public.assessments a where a.id=x and public.can_manage_course(a.course_id)) $$;
create function public.student_content(c uuid,t uuid,l uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select public.current_app_role()='STUDENT' and public.can_access_course(c) and (t is null or exists(select 1 from public.course_topics x where x.id=t and x.status='PUBLISHED' and x.deleted_at is null)) and (l is null or exists(select 1 from public.lessons x join public.course_topics z on z.id=x.topic_id where x.id=l and x.status='PUBLISHED' and z.status='PUBLISHED' and x.deleted_at is null)) $$;
create function public.student_can_submit(x uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select exists(select 1 from public.assignments a where a.id=x and a.status='PUBLISHED' and a.deleted_at is null and public.student_content(a.course_id,a.topic_id,a.lesson_id) and (now()<=a.due_at or (a.allow_late and now()<=a.late_close_at))) $$;
create function public.student_can_take(x uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select exists(select 1 from public.assessments a where a.id=x and a.status='PUBLISHED' and a.deleted_at is null and public.student_content(a.course_id,a.topic_id,a.lesson_id) and now() between a.open_at and a.close_at) $$;
create function public.auth_user_profile() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ begin insert into public.profiles(id,email,full_name,role) values(new.id,coalesce(new.email,''),coalesce(new.raw_user_meta_data->>'full_name',''),'STUDENT') on conflict(id) do update set email=excluded.email; return new; end $$;
create trigger auth_profile after insert or update of email on auth.users for each row execute function public.auth_user_profile();
create function public.create_class_with_code(n text,g smallint default null,y text default null) returns table(class_id uuid,join_code text) language plpgsql security definer set search_path=public,pg_temp as $$ declare c uuid; k text; begin if auth.uid() is null or public.current_app_role()<>'TEACHER' then raise exception 'Only teachers can create a class'; end if; insert into public.classes(name,grade,school_year,owner_teacher_id) values(trim(n),g,y,auth.uid()) returning id into c; loop k=upper(substr(encode(gen_random_bytes(8),'hex'),1,8)); exit when not exists(select 1 from public.class_invites where code=k); end loop; insert into public.class_invites(class_id,code,created_by) values(c,k,auth.uid()); return query select c,k; end $$;
create function public.join_class_with_code(k text) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare c uuid; begin if auth.uid() is null or public.current_app_role()<>'STUDENT' then raise exception 'Only students can join a class'; end if; select i.class_id into c from public.class_invites i join public.classes x on x.id=i.class_id where upper(i.code)=upper(trim(k)) and i.revoked_at is null and (i.expires_at is null or i.expires_at>now()) and x.deleted_at is null limit 1; if c is null then raise exception 'Invalid or expired class code'; end if; insert into public.class_members(class_id,student_id) values(c,auth.uid()) on conflict do nothing; return c; end $$;
create function public.student_assessment_questions(x uuid) returns table(question_id uuid,content text,kind text,options jsonb,weight numeric,display_order integer) language plpgsql security definer set search_path=public,pg_temp as $$ begin if not public.can_access_course((select course_id from public.assessments where id=x)) then raise exception 'Assessment unavailable'; end if; if public.current_app_role()='STUDENT' and not public.student_can_take(x) then raise exception 'Assessment closed'; end if; return query select q.id,q.content,q.kind,q.options,aq.weight,aq.display_order from public.assessment_questions aq join public.questions q on q.id=aq.question_id where aq.assessment_id=x and q.deleted_at is null order by aq.display_order; end $$;
create function public.protect_student_grades() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ begin if auth.uid() is not null and public.current_app_role()='STUDENT' then if tg_table_name='submission_answers' and (new.score is distinct from old.score or new.feedback is distinct from old.feedback or new.graded_by is distinct from old.graded_by or new.graded_at is distinct from old.graded_at) then raise exception 'Students cannot change grades'; end if; if tg_table_name='assessment_attempts' and (new.total_score is distinct from old.total_score or new.graded_at is distinct from old.graded_at or new.student_id is distinct from old.student_id or new.assessment_id is distinct from old.assessment_id) then raise exception 'Students cannot change grades or ownership'; end if; if tg_table_name='assignment_submissions' and (new.student_id is distinct from old.student_id or new.assignment_id is distinct from old.assignment_id or new.score is distinct from old.score or new.feedback is distinct from old.feedback or new.graded_by is distinct from old.graded_by or new.graded_at is distinct from old.graded_at) then raise exception 'Students cannot change grades or ownership'; end if; end if; return new; end $$;
create trigger protect_answer_grade before update on public.submission_answers for each row execute function public.protect_student_grades();
create trigger protect_attempt_grade before update on public.assessment_attempts for each row execute function public.protect_student_grades();
create trigger protect_assignment_grade before update on public.assignment_submissions for each row execute function public.protect_student_grades();
create function public.can_read_resource(p text) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select exists(select 1 from public.resources r where r.storage_path=p and r.deleted_at is null and public.can_access_course(r.course_id) and (public.current_app_role()='TEACHER' or r.lesson_id is null or exists(select 1 from public.lessons l join public.course_topics t on t.id=l.topic_id where l.id=r.lesson_id and l.status='PUBLISHED' and t.status='PUBLISHED'))) $$;

alter table public.profiles enable row level security; alter table public.classes enable row level security; alter table public.class_members enable row level security; alter table public.class_invites enable row level security; alter table public.courses enable row level security; alter table public.course_topics enable row level security; alter table public.lessons enable row level security; alter table public.learning_objectives enable row level security; alter table public.resources enable row level security; alter table public.assignments enable row level security; alter table public.assignment_submissions enable row level security; alter table public.questions enable row level security; alter table public.assessments enable row level security; alter table public.assessment_questions enable row level security; alter table public.assessment_attempts enable row level security; alter table public.submission_answers enable row level security; alter table public.mastery enable row level security; alter table public.knowledge_gaps enable row level security; alter table public.recommendations enable row level security; alter table public.notifications enable row level security;
create policy profile_self_read on public.profiles for select to authenticated using(id=auth.uid() or exists(select 1 from public.class_members m join public.classes c on c.id=m.class_id where m.student_id=profiles.id and c.owner_teacher_id=auth.uid()));
create policy profile_update_self on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy class_read on public.classes for select to authenticated using(public.can_access_class(id)); create policy class_insert on public.classes for insert to authenticated with check(owner_teacher_id=auth.uid() and public.current_app_role()='TEACHER'); create policy class_update on public.classes for update to authenticated using(public.can_manage_class(id)) with check(public.can_manage_class(id)); create policy class_delete on public.classes for delete to authenticated using(public.can_manage_class(id));
create policy member_read on public.class_members for select to authenticated using(student_id=auth.uid() or public.can_manage_class(class_id)); create policy member_teacher_add on public.class_members for insert to authenticated with check(public.can_manage_class(class_id) and exists(select 1 from public.profiles p where p.id=student_id and p.role='STUDENT')); create policy member_teacher_remove on public.class_members for delete to authenticated using(public.can_manage_class(class_id));
create policy invite_teacher_all on public.class_invites for all to authenticated using(public.can_manage_class(class_id)) with check(public.can_manage_class(class_id) and created_by=auth.uid());
create policy course_read on public.courses for select to authenticated using(public.can_access_class(class_id)); create policy course_teacher_all on public.courses for all to authenticated using(public.can_manage_class(class_id)) with check(public.can_manage_class(class_id));
create policy topic_read on public.course_topics for select to authenticated using(public.can_access_course(course_id) and (public.current_app_role()='TEACHER' or (status='PUBLISHED' and deleted_at is null))); create policy topic_teacher_all on public.course_topics for all to authenticated using(public.can_manage_course(course_id)) with check(public.can_manage_course(course_id));
create policy lesson_read on public.lessons for select to authenticated using(public.can_access_course(course_id) and (public.current_app_role()='TEACHER' or (status='PUBLISHED' and deleted_at is null and exists(select 1 from public.course_topics t where t.id=topic_id and t.status='PUBLISHED')))); create policy lesson_teacher_all on public.lessons for all to authenticated using(public.can_manage_course(course_id)) with check(public.can_manage_course(course_id));
create policy objective_read on public.learning_objectives for select to authenticated using(exists(select 1 from public.lessons l where l.id=lesson_id and public.can_access_course(l.course_id) and (public.current_app_role()='TEACHER' or l.status='PUBLISHED'))); create policy objective_teacher_all on public.learning_objectives for all to authenticated using(exists(select 1 from public.lessons l where l.id=lesson_id and public.can_manage_course(l.course_id))) with check(exists(select 1 from public.lessons l where l.id=lesson_id and public.can_manage_course(l.course_id)));
create policy resource_read on public.resources for select to authenticated using(public.can_read_resource(storage_path)); create policy resource_teacher_all on public.resources for all to authenticated using(public.can_manage_course(course_id)) with check(public.can_manage_course(course_id) and uploaded_by=auth.uid());
create policy assignment_read on public.assignments for select to authenticated using(public.can_access_course(course_id) and (public.can_manage_course(course_id) or (status='PUBLISHED' and deleted_at is null and public.student_content(course_id,topic_id,lesson_id)))); create policy assignment_teacher_all on public.assignments for all to authenticated using(public.can_manage_course(course_id)) with check(public.can_manage_course(course_id) and created_by=auth.uid());
create policy assignment_submission_read on public.assignment_submissions for select to authenticated using(student_id=auth.uid() or public.can_manage_assignment(assignment_id)); create policy assignment_submission_insert on public.assignment_submissions for insert to authenticated with check(student_id=auth.uid() and public.student_can_submit(assignment_id)); create policy assignment_submission_update on public.assignment_submissions for update to authenticated using((student_id=auth.uid() and score is null) or public.can_manage_assignment(assignment_id)) with check((student_id=auth.uid() and score is null) or public.can_manage_assignment(assignment_id)); create policy assignment_submission_delete on public.assignment_submissions for delete to authenticated using(public.can_manage_assignment(assignment_id));
create policy question_teacher_all on public.questions for all to authenticated using(public.can_manage_course(course_id)) with check(public.can_manage_course(course_id) and created_by=auth.uid());
create policy assessment_read on public.assessments for select to authenticated using(public.can_access_course(course_id) and (public.can_manage_course(course_id) or (status='PUBLISHED' and deleted_at is null and public.student_content(course_id,topic_id,lesson_id)))); create policy assessment_teacher_all on public.assessments for all to authenticated using(public.can_manage_course(course_id)) with check(public.can_manage_course(course_id) and created_by=auth.uid());
create policy assessment_questions_teacher on public.assessment_questions for all to authenticated using(public.can_manage_assessment(assessment_id)) with check(public.can_manage_assessment(assessment_id));
create policy attempt_read on public.assessment_attempts for select to authenticated using(student_id=auth.uid() or public.can_manage_assessment(assessment_id)); create policy attempt_insert on public.assessment_attempts for insert to authenticated with check(student_id=auth.uid() and public.student_can_take(assessment_id)); create policy attempt_update on public.assessment_attempts for update to authenticated using((student_id=auth.uid() and status='IN_PROGRESS') or public.can_manage_assessment(assessment_id)) with check((student_id=auth.uid() and status in ('IN_PROGRESS','SUBMITTED')) or public.can_manage_assessment(assessment_id));
create policy answers_read on public.submission_answers for select to authenticated using(exists(select 1 from public.assessment_attempts a where a.id=attempt_id and (a.student_id=auth.uid() or public.can_manage_assessment(a.assessment_id)))); create policy answers_student_write on public.submission_answers for all to authenticated using(exists(select 1 from public.assessment_attempts a where a.id=attempt_id and a.student_id=auth.uid() and a.status='IN_PROGRESS')) with check(exists(select 1 from public.assessment_attempts a where a.id=attempt_id and a.student_id=auth.uid() and a.status='IN_PROGRESS')); create policy answers_teacher_grade on public.submission_answers for update to authenticated using(exists(select 1 from public.assessment_attempts a where a.id=attempt_id and public.can_manage_assessment(a.assessment_id))) with check(exists(select 1 from public.assessment_attempts a where a.id=attempt_id and public.can_manage_assessment(a.assessment_id) and graded_by=auth.uid()));
create policy mastery_read on public.mastery for select to authenticated using(student_id=auth.uid() or exists(select 1 from public.learning_objectives o join public.lessons l on l.id=o.lesson_id join public.courses c on c.id=l.course_id join public.class_members m on m.class_id=c.class_id where o.id=objective_id and m.student_id=mastery.student_id and public.can_manage_class(c.class_id)));
create policy gap_read on public.knowledge_gaps for select to authenticated using(student_id=auth.uid() or exists(select 1 from public.learning_objectives o join public.lessons l on l.id=o.lesson_id join public.courses c on c.id=l.course_id join public.class_members m on m.class_id=c.class_id where o.id=objective_id and m.student_id=knowledge_gaps.student_id and public.can_manage_class(c.class_id)));
create policy recommendation_read on public.recommendations for select to authenticated using(student_id=auth.uid() or exists(select 1 from public.learning_objectives o join public.lessons l on l.id=o.lesson_id join public.courses c on c.id=l.course_id join public.class_members m on m.class_id=c.class_id where o.id=objective_id and m.student_id=recommendations.student_id and public.can_manage_class(c.class_id))); create policy recommendation_respond on public.recommendations for update to authenticated using(student_id=auth.uid()) with check(student_id=auth.uid() and status in ('ACCEPTED','DISMISSED'));
create policy notification_read on public.notifications for select to authenticated using(user_id=auth.uid()); create policy notification_update on public.notifications for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
revoke all on public.profiles from anon,authenticated; grant select on public.profiles to authenticated; grant update(full_name) on public.profiles to authenticated;
grant select,insert,update,delete on public.classes,public.class_members,public.class_invites,public.courses,public.course_topics,public.lessons,public.learning_objectives,public.resources,public.assignments,public.assignment_submissions,public.questions,public.assessments,public.assessment_questions,public.assessment_attempts,public.submission_answers,public.knowledge_gaps,public.recommendations,public.notifications to authenticated; grant select on public.mastery to authenticated;
grant execute on function public.create_class_with_code(text,smallint,text),public.join_class_with_code(text),public.student_assessment_questions(uuid) to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('educmind-resources','educmind-resources',false,52428800,array['application/pdf','image/png','image/jpeg','image/webp','text/plain','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.openxmlformats-officedocument.presentationml.presentation','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet']) on conflict(id) do nothing;
create policy educmind_resource_read on storage.objects for select to authenticated using(bucket_id='educmind-resources' and public.can_read_resource(name)); create policy educmind_resource_insert on storage.objects for insert to authenticated with check(bucket_id='educmind-resources' and public.can_manage_class((storage.foldername(name))[1]::uuid)); create policy educmind_resource_update on storage.objects for update to authenticated using(bucket_id='educmind-resources' and public.can_manage_class((storage.foldername(name))[1]::uuid)) with check(bucket_id='educmind-resources' and public.can_manage_class((storage.foldername(name))[1]::uuid)); create policy educmind_resource_delete on storage.objects for delete to authenticated using(bucket_id='educmind-resources' and public.can_manage_class((storage.foldername(name))[1]::uuid));
